// VisitConcOption is the `_concOption` slot-visit strategy: when subject is `concOption`,
// applies each constituent strategy to the matching child slot and
// rebuilds the term iff at least one child changed. Fails with
// sl.ErrVisitFailure when subject isn't `concOption`.
type VisitConcOption struct {
	sl.AbstractStrategy
	args []sl.Strategy
}

// NewVisitConcOption builds the slot-visit strategy with the supplied per-slot
// sub-strategies.
func NewVisitConcOption(args ...sl.Strategy) *VisitConcOption {
	return &VisitConcOption{args: args}
}

func (s *VisitConcOption) VisitLight(subject any, intro sl.Introspector) (any, error) {
	if _, ok := subject.(*ConcOptionOptionList); !ok {
		return subject, sl.ErrVisitFailure
	}
	// Variadic alt: visit every element with args[0] (Java's
	// `_concX` invokes the sub-strategy on each list element).
	if len(s.args) == 0 {
		return subject, nil
	}
	count := intro.GetChildCount(subject)
	var newChildren []any
	for i := 0; i < count; i++ {
		oldChild := intro.GetChildAt(subject, i)
		newChild, err := s.args[0].VisitLight(oldChild, intro)
		if err != nil {
			return subject, err
		}
		if newChildren != nil {
			newChildren[i] = newChild
		} else if newChild != oldChild {
			newChildren = intro.GetChildren(subject)
			newChildren[i] = newChild
		}
	}
	if newChildren != nil {
		return intro.SetChildren(subject, newChildren), nil
	}
	return subject, nil
}

func (s *VisitConcOption) ChildCount() int                 { return len(s.args) }
func (s *VisitConcOption) ChildAt(i int) sl.Strategy       { return s.args[i] }
func (s *VisitConcOption) SetChildAt(i int, v sl.Strategy) { s.args[i] = v }

func (s *VisitConcOption) VisitEnv(intro sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*ConcOptionOptionList); !ok {
		return sl.StatusFailure
	}
	return sl.VisitCongruence(s.GetEnvironment(), intro, s.args, true)
}
func (s *VisitConcOption) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *VisitConcOption) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*VisitConcOption)(nil)

// SymbolName is the symbol of the Java term: ConsconcOption or EmptyconcOption.
func (t *ConcOptionOptionList) SymbolName() string {
	if t.empty {
		return "EmptyconcOption"
	}
	return "ConsconcOption"
}

func (t *ConcOptionOptionList) IsConsconcOption() bool  { return !t.empty }
func (t *ConcOptionOptionList) IsEmptyconcOption() bool { return t.empty }

func (t *ConcOptionOptionList) GetHeadconcOption() Option {
	if t.empty {
		panic(&aterm.GomError{Msg: "This OptionList has no HeadconcOption"})
	}
	return t.head
}
func (t *ConcOptionOptionList) GetTailconcOption() OptionList {
	if t.empty {
		panic(&aterm.GomError{Msg: "This OptionList has no TailconcOption"})
	}
	return t.tail
}

// Length is Java's length(): the number of elements of the list (a
// tail that is not a concOption list counts as one element).
func (t *ConcOptionOptionList) Length() int {
	res := 0
	var tl OptionList = t
	for {
		c, ok := tl.(*ConcOptionOptionList)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*ConcOptionOptionList); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a concOption list.
func (t *ConcOptionOptionList) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur OptionList = t
	for {
		c, ok := cur.(*ConcOptionOptionList)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*ConcOptionOptionList); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsConcOption
// (through the hooks).
func (t *ConcOptionOptionList) Reverse() OptionList {
	if t.empty {
		return t
	}
	var cur OptionList = t
	var rev OptionList = EmptyConcOption()
	for {
		c, ok := cur.(*ConcOptionOptionList)
		if !ok || c.empty {
			break
		}
		rev = ConsConcOption(c.head, rev)
		cur = c.tail
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsConcOption (through the hooks).
func (t *ConcOptionOptionList) Append(element Option) OptionList {
	var heads []Option
	var cur OptionList = t
	for {
		c, ok := cur.(*ConcOptionOptionList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res OptionList
	if c, ok := cur.(*ConcOptionOptionList); ok && c.empty {
		res = ConsConcOption(element, cur)
	} else {
		res = ConsConcOption(element, cur)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsConcOption(heads[i], res)
	}
	return res
}

func (t *ConcOptionOptionList) CompareTo(o any) int {
	for {
		ao := o.(OptionList)
		if ao == OptionList(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcOptionOptionList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcOptionOptionList)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *ConcOptionOptionList) CompareToLPO(o any) int {
	for {
		ao := o.(OptionList)
		if ao == OptionList(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcOptionOptionList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcOptionOptionList)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcOptionOptionList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []Option
	var cur OptionList = t
	for {
		c, ok := cur.(*ConcOptionOptionList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcOptionOptionList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcOptionOptionList is Java Gom's concOption.fromTerm: an application of concOption, or a
// list (of ToATerm), of convertible elements.
func fromTermConcOptionOptionList(trm aterm.ATerm, conv aterm.ATermConverter) (res OptionList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "concOption" {
		elems := make([]Option, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = OptionFromTermConv(a, conv)
		}
		return MakeConcOption(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a concOption (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []Option
		for !list.IsEmpty() {
			elems = append(elems, OptionFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcOption(elems...), true
	}
	return nil, false
}
